-- Replace all volunteers with new data from CSV
-- This will delete all existing volunteers and insert 260 new ones

BEGIN;

-- Delete all existing attendance records first (to avoid foreign key constraint issues)
DELETE FROM attendance;

-- Delete all existing volunteers
DELETE FROM volunteers;

-- Reset the volunteers id sequence
ALTER SEQUENCE volunteers_id_seq RESTART WITH 1;

-- Insert new volunteers with generated UUIDs for qr_code

COMMIT;
